  static Future<Report> default_() =>
      RustLib.instance.api.crateApiWireReportDefault();

  @override
  int get hashCode =>
      changed.hashCode ^
      created.hashCode ^
      removed.hashCode ^
      grids.hashCode ^
      tags.hashCode ^
      recalculated.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Report &&
          runtimeType == other.runtimeType &&
          changed == other.changed &&
          created == other.created &&
          removed == other.removed &&
          grids == other.grids &&
          tags == other.tags &&
          recalculated == other.recalculated;
}

